// v2.13 算法移植，坐标使用运行时的 32px 逻辑轨道。
const motionPreference = typeof matchMedia === "function" ? matchMedia("(prefers-reduced-motion: reduce)") : null;

// 复用渐隐光尾，避免逐粒子逐帧新建渐变。
function makeStreak(h, endColor, middleColor) {
  const strip = h.createCanvas(64, 2);
  const ctx = strip.getContext("2d");
  const grad = ctx.createLinearGradient(0, 0, strip.width, 0);
  grad.addColorStop(0, "rgba(255, 255, 255, 0)");
  if (middleColor) grad.addColorStop(0.6, middleColor);
  grad.addColorStop(1, endColor);
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, strip.width, strip.height);
  return strip;
}

return {
  init({ h }) {
    const rand = h.rand(21310);
    const particles = Array.from({ length: 30 }, () => ({
      relDist: rand(),
      y: rand() * 32,
      vx: 0.6 + rand() * 2.4,
      size: 1.2 + rand() * 3.6
    }));
    return { lastTime: null, wasMax: false, afterglow: 0, particles };
  },
  draw(ctx, s) {
    const { width, height, pal, dark, state } = s;
    const thumbX = Math.max(0, Math.min(s.end, width));
    if (thumbX <= 0) return;
    const L2 = s.high;
    const L3 = s.max;
    const reduced = Boolean(motionPreference?.matches);
    const time = reduced ? 0 : s.time;
    const burstT = reduced ? 0 : s.burst;
    const isBursting = burstT > 0;
    const isMaxEffort = L3 >= 0.94;
    const secondary = s.monet?.enabled ? s.monet.secondary : pal;
    const cruisePulse = isMaxEffort ? 0.5 + 0.5 * Math.sin(time * 1.8) : 0;

    // 用运行时已调整流速的时间推进粒子，流速归零时定格。
    const elapsed = state.lastTime === null || reduced ? 0 : Math.max(0, time - state.lastTime);
    state.lastTime = time;
    const frameStep = Math.min(s.dt * 4, elapsed / 0.035);
    const currentRatio = s.ratio ?? thumbX / Math.max(1, width);
    const overdrive = isMaxEffort ? 1 : Math.max(0, (currentRatio - 0.65) / 0.35);
    let targetBudget = 0;
    if (currentRatio >= 0.95) targetBudget = Math.round(60 + ((currentRatio - 0.95) / 0.05) * 68);
    else if (currentRatio >= 0.4) targetBudget = Math.round(18 + ((currentRatio - 0.4) / 0.55) * 34);
    else if (currentRatio >= 0.02) targetBudget = Math.round(6 + (currentRatio / 0.4) * 8);
    targetBudget = Math.min(state.particles.length, isBursting ? 128 : targetBudget);
    const { particles } = state;

    const light = secondary.light(0.85);
    if (!state.streakWhite) state.streakWhite = makeStreak(s.h, "rgba(255, 255, 255, 0.95)");
    if (state.streakLightColor !== light) {
      state.streakLight = makeStreak(s.h, light);
      state.streakLightColor = light;
    }

    ctx.globalCompositeOperation = dark ? "lighter" : "source-over";
    state.afterglow = state.wasMax && !isMaxEffort ? 1 : Math.max(0, state.afterglow - s.dt / 24);
    state.wasMax = isMaxEffort;
    const afterglowT = reduced ? 0 : state.afterglow;

    // 河床：左端透明、向右渐亮，避免出现硬边
    const bedGrad = ctx.createLinearGradient(0, 0, thumbX, 0);
    bedGrad.addColorStop(0, pal.deep(0.06));
    bedGrad.addColorStop(0.55, pal.main(0.18));
    bedGrad.addColorStop(0.88, pal.light(0.42));
    bedGrad.addColorStop(1, "rgba(255, 255, 255, 0.85)");
    ctx.fillStyle = bedGrad;
    ctx.fillRect(0, 0, thumbX, height);

    // 中央流动脊线
    const cgSpine = (x) => height / 2
      + Math.sin(x * 0.018 - time * 2.1) * height * 0.16
      + Math.sin(x * 0.062 + time * 3.3) * height * 0.05;

    // 主拖尾：尾部零宽度张开到头部满宽（外层轻、内层实）
    const tailLen = Math.min(thumbX, 110 + height * 3.2 + overdrive * 170);
    const tailX = Math.max(0, thumbX - tailLen);
    const tailSpan = Math.max(1, thumbX - tailX);
    for (let layer = 0; layer < 3; layer++) {
      const halfMax = height * (0.42 - layer * 0.1) * (1 + overdrive * 0.15);
      const bodyGrad = ctx.createLinearGradient(tailX, 0, thumbX, 0);
      bodyGrad.addColorStop(0, "rgba(255, 255, 255, 0)");
      bodyGrad.addColorStop(0.45, pal.main(0.1 + layer * 0.05));
      bodyGrad.addColorStop(0.82, pal.light(0.3 + layer * 0.08));
      bodyGrad.addColorStop(1, layer === 1 ? "rgba(255, 255, 255, 0.9)" : pal.light(0.45));
      ctx.beginPath();
      for (let x = tailX; x <= thumbX; x += 3) {
        const half = halfMax * Math.pow((x - tailX) / tailSpan, 1.7);
        const y = cgSpine(x) - half;
        if (x === tailX) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      for (let x = thumbX; x >= tailX; x -= 3) {
        const half = halfMax * Math.pow((x - tailX) / tailSpan, 1.7);
        ctx.lineTo(x, cgSpine(x) + half);
      }
      ctx.closePath();
      ctx.fillStyle = bodyGrad;
      ctx.fill();
    }

    // 流光细丝：3 条沿脊线走的高亮丝，越靠尾部越淡（拖尾的"流"感来源）
    for (let f = 0; f < 3; f++) {
      const off = (f - 1) * height * 0.12;
      const filGrad = ctx.createLinearGradient(tailX, 0, thumbX, 0);
      filGrad.addColorStop(0, "rgba(255, 255, 255, 0)");
      filGrad.addColorStop(0.5, pal.light(0.22));
      filGrad.addColorStop(0.86, pal.light(0.7));
      filGrad.addColorStop(1, "rgba(255, 255, 255, 0.95)");
      ctx.strokeStyle = filGrad;
      ctx.lineWidth = f === 1 ? 1.8 : 1.1;
      ctx.beginPath();
      for (let x = tailX; x <= thumbX; x += 3) {
        const t = (x - tailX) / tailSpan;
        const y = cgSpine(x) + off * Math.pow(t, 1.3)
          + Math.sin(x * 0.11 + time * 4.2 + f * 2.1) * height * 0.05 * t;
        if (x === tailX) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.stroke();
    }

    // 拖尾上的星屑：越靠尾部越小越淡，并沿流向拉长
    for (let i = 0; i < Math.min(30, targetBudget); i++) {
      const p = particles[i];
      p.relDist += (0.16 + p.vx * 0.1) * frameStep * (1 + overdrive * 0.9);
      if (p.relDist > 1) p.relDist = 0;
      const sx = thumbX - p.relDist * tailLen;
      if (sx < 0) continue;
      const t = 1 - p.relDist;
      const sy = cgSpine(sx) + (p.y / 32 - 0.5) * height * 0.8 * Math.pow(t, 1.2);
      const size = (0.7 + p.size * 0.34) * (0.35 + t);
      const streak = 3 + 18 * t;
      const strip = i % 2 === 0 ? state.streakWhite : state.streakLight;
      ctx.drawImage(strip, sx - streak, sy - size * 0.5, streak, size);
    }

    // 头部热核：明亮光斑 + 十字星芒
    const cgPulse = 1 + 0.18 * Math.sin(time * 5.2);
    const cgCore = (3.0 + overdrive * 2.2) * cgPulse;
    const coreGrad = ctx.createRadialGradient(thumbX, height / 2, 0, thumbX, height / 2, cgCore * 4.2);
    coreGrad.addColorStop(0, "rgba(255, 255, 255, 1)");
    coreGrad.addColorStop(0.35, pal.light(0.8));
    coreGrad.addColorStop(1, "rgba(255, 255, 255, 0)");
    ctx.fillStyle = coreGrad;
    ctx.beginPath();
    ctx.arc(thumbX, height / 2, cgCore * 4.2, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "rgba(255, 255, 255, 0.9)";
    ctx.fillRect(thumbX - cgCore * 2.6, height / 2 - 0.6, cgCore * 5.2, 1.2);
    ctx.fillRect(thumbX - 0.6, height / 2 - cgCore * 2.6, 1.2, cgCore * 5.2);
    // High：再加 3 条流光细丝
    if (L2 > 0.01) {
      for (let f3 = 0; f3 < 3; f3++) {
        const off3 = (f3 - 1) * height * 0.3;
        ctx.strokeStyle = pal.light(0.28 * L2);
        ctx.lineWidth = 0.9;
        ctx.beginPath();
        for (let x = tailX; x <= thumbX; x += 4) {
          const t3 = (x - tailX) / tailSpan;
          const y = height / 2 + off3 * Math.pow(t3, 1.2)
            + Math.sin(x * 0.06 + time * 3 + f3 * 2) * height * 0.06 * t3;
          if (x === tailX) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        }
        ctx.stroke();
      }
    }
    // Max：头部热核放大 + 二次彗尾
    if (L3 > 0.01) {
      const bigR = height * 1.5;
      const bg4 = ctx.createRadialGradient(thumbX, height / 2, 0, thumbX, height / 2, bigR);
      bg4.addColorStop(0, "rgba(255, 255, 255, " + (0.85 * L3) + ")");
      bg4.addColorStop(0.35, pal.light(0.45 * L3));
      bg4.addColorStop(1, "rgba(255, 255, 255, 0)");
      ctx.fillStyle = bg4;
      ctx.beginPath();
      ctx.arc(thumbX, height / 2, bigR, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = "rgba(255, 255, 255, " + (0.7 * L3) + ")";
      ctx.fillRect(thumbX - 24, height / 2 - 1.2, 24, 2.4);
    }

    // 【L2 结构层】克制的顶边高光与丝滑掠过扫光，让 High 更有层次又不遮挡主体动效
    if (L2 > 0.01) {
      const topSheen = ctx.createLinearGradient(0, 0, thumbX, 0);
      topSheen.addColorStop(0, "rgba(255, 255, 255, 0)");
      topSheen.addColorStop(0.5, `rgba(255, 255, 255, ${(0.18 * L2).toFixed(3)})`);
      topSheen.addColorStop(1, `rgba(255, 255, 255, ${(0.36 * L2).toFixed(3)})`);
      ctx.fillStyle = topSheen;
      ctx.fillRect(0, 1.0, thumbX, 1.2);

      const sweepX = ((time * 0.36) % 1) * (thumbX + 150) - 75;
      const sweepGrad = ctx.createLinearGradient(sweepX - 50, 0, sweepX + 50, 0);
      sweepGrad.addColorStop(0, "rgba(255, 255, 255, 0)");
      sweepGrad.addColorStop(0.5, `rgba(255, 255, 255, ${(0.18 * L2).toFixed(3)})`);
      sweepGrad.addColorStop(1, "rgba(255, 255, 255, 0)");
      ctx.fillStyle = sweepGrad;
      const left = Math.max(0, sweepX - 50);
      const right = Math.min(thumbX, sweepX + 50);
      if (right > left) ctx.fillRect(left, 0, right - left, height);
    }

    // 【L3 高能层】美学克制版 Max 光冠：径向柔核 + 6 道细光晕 + 2 圈柔波，告别杂乱激光与方块噪点
    if (L3 > 0.01) {
      const crownR = Math.max(height * 1.45, 38);
      const crown = ctx.createRadialGradient(thumbX, height * 0.5, 0, thumbX, height * 0.5, crownR);
      crown.addColorStop(0, `rgba(255, 255, 255, ${(0.42 * L3 * (0.88 + 0.12 * cruisePulse)).toFixed(3)})`);
      crown.addColorStop(0.45, pal.light(0.24 * L3));
      crown.addColorStop(1, "rgba(255, 255, 255, 0)");
      ctx.fillStyle = crown;
      ctx.beginPath();
      ctx.arc(thumbX, height * 0.5, crownR, 0, Math.PI * 2);
      ctx.fill();

      const rayR = Math.max(height * 0.95, 28);
      for (let r = 0; r < 6; r++) {
        const ra = time * 1.15 + (r / 6) * Math.PI * 2;
        const rl = rayR * (0.55 + 0.45 * Math.sin(time * 2.1 + r * 1.4));
        const rayGrad = ctx.createLinearGradient(thumbX, height * 0.5,
          thumbX + Math.cos(ra) * rl, height * 0.5 + Math.sin(ra) * rl);
        rayGrad.addColorStop(0, `rgba(255, 255, 255, ${(0.34 * L3).toFixed(3)})`);
        rayGrad.addColorStop(1, "rgba(255, 255, 255, 0)");
        ctx.strokeStyle = rayGrad;
        ctx.lineWidth = 1.1;
        ctx.beginPath();
        ctx.moveTo(thumbX, height * 0.5);
        ctx.lineTo(thumbX + Math.cos(ra) * rl, height * 0.5 + Math.sin(ra) * rl);
        ctx.stroke();
      }

      for (let k = 0; k < 2; k++) {
        const ph = (time * 0.68 + k * 0.5) % 1;
        const rr = ph * width * 0.42;
        const aa = (1 - ph) * 0.30 * L3;
        if (aa < 0.02) continue;
        ctx.strokeStyle = `rgba(255, 255, 255, ${aa.toFixed(3)})`;
        ctx.lineWidth = 1.5 * (1 - ph) + 0.5;
        ctx.beginPath();
        ctx.arc(thumbX, height * 0.5, rr, Math.PI * 0.5, Math.PI * 1.5);
        ctx.stroke();
      }

      const rimGrad = ctx.createLinearGradient(0, 0, thumbX, 0);
      rimGrad.addColorStop(0, "rgba(255, 255, 255, 0)");
      rimGrad.addColorStop(Math.min(1, Math.max(0, 0.55 + 0.3 * Math.sin(time * 0.8))), `rgba(255, 255, 255, ${(0.32 * L3).toFixed(3)})`);
      rimGrad.addColorStop(1, "rgba(255, 255, 255, 0)");
      ctx.fillStyle = rimGrad;
      ctx.fillRect(0, 0.6, thumbX, 1.2);
      ctx.fillRect(0, height - 1.8, thumbX, 1.2);
    }

    if (isBursting) {
      const shockRadius = (1 - burstT) * width * 0.85;
      ctx.save();
      ctx.strokeStyle = dark ? `rgba(255, 255, 255, ${burstT * 0.85})` : pal.main(burstT * 0.75);
      ctx.lineWidth = 3.5 * burstT;
      ctx.beginPath();
      ctx.arc(thumbX, height / 2, shockRadius, 0, Math.PI * 2);
      ctx.stroke();

      // 全轨高光冲洗 (Flash Wash)
      ctx.fillStyle = dark ? `rgba(255, 255, 255, ${burstT * 0.35})` : `rgba(255, 255, 255, ${burstT * 0.2})`;
      ctx.fillRect(0, 0, thumbX, height);
      ctx.restore();
    }

    // ---------------------------------------------------------
    // ③ 降档余韵尾迹 (Afterglow: 0.4s)
    // ---------------------------------------------------------
    if (afterglowT > 0) {
      ctx.save();
      ctx.fillStyle = pal.light(afterglowT * 0.25);
      ctx.fillRect(0, 0, thumbX, height);
      ctx.restore();
    }
  }
};
